from collections import defaultdict
from collections.abc import Sequence
from typing import Final

from tools.Measurement.MeasurementRow import MeasurementRow


class MeasurementReport:
    """Renders measurements as Markdown: one row per file, then a summary per type."""

    TITLE: Final = "# Parse time and memory per file"
    NOTE: Final = (
        "Generated by `uv run python -m tools.Measurement tests/corpus docs/measurements.md`.\n"
        "Time is the parse inside the worker process. Memory is the worker's peak resident\n"
        "size, which includes the Python interpreter and libraries (about 30 MB)."
    )

    def render(self, rows: Sequence[MeasurementRow]) -> str:
        """Build the report.

        Args:
            rows: The measurements.

        Returns:
            The Markdown text.
        """
        lines = [self.TITLE, "", self.NOTE, "", "## Per file", ""]
        lines += ["| File | Type | Size (bytes) | Outcome | Time (ms) | Peak memory (MB) |"]
        lines += ["|---|---|---|---|---|---|"]
        lines += [self._file_line(row) for row in rows]
        lines += ["", "## Per type (worst case)", ""]
        lines += ["| Type | Files | Max time (ms) | Max peak memory (MB) |", "|---|---|---|---|"]
        lines += self._type_lines(rows)
        return "\n".join(lines) + "\n"

    def _file_line(self, row: MeasurementRow) -> str:
        cells = (
            row.file,
            row.detected_type,
            str(row.size_bytes),
            row.outcome,
            self._number(row.elapsed_ms),
            self._mb(row.peak_memory_kb),
        )
        return f"| {' | '.join(cells)} |"

    def _type_lines(self, rows: Sequence[MeasurementRow]) -> list[str]:
        by_type: defaultdict[str, list[MeasurementRow]] = defaultdict(list)
        for row in rows:
            by_type[row.detected_type].append(row)
        return [self._type_line(kind, group) for kind, group in sorted(by_type.items())]

    def _type_line(self, kind: str, group: Sequence[MeasurementRow]) -> str:
        times = [row.elapsed_ms for row in group if row.elapsed_ms is not None]
        memory = [row.peak_memory_kb for row in group if row.peak_memory_kb is not None]
        worst_time = max(times) if times else None
        worst_memory = max(memory) if memory else None
        return f"| {kind} | {len(group)} | {self._number(worst_time)} | {self._mb(worst_memory)} |"

    @staticmethod
    def _number(value: int | None) -> str:
        return "-" if value is None else str(value)

    @staticmethod
    def _mb(kilobytes: int | None) -> str:
        return "-" if kilobytes is None else f"{kilobytes / 1024:.1f}"
